.fileitem .fi-icon {
  width: 34px; height: 34px;
  border-radius: 9px;
  display: grid;
  place-items: center;
  background: var(--surface-3);
  color: var(--ink-2);
  flex: 0 0 auto;
}
.fileitem .fi-icon svg { width: 17px; height: 17px; }
.fileitem .fi-body { min-width: 0; flex: 1; }
.fileitem .fi-name {
  font-size: 13.5px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.fileitem .fi-state { font-size: 12px; color: var(--ink-3); }
.fileitem.done .fi-icon { background: var(--ok-soft); color: var(--ok); }
.fileitem.error .fi-icon { background: var(--danger-soft); color: var(--danger); }
.fileitem.error .fi-state { color: var(--danger); }

.spinner {
  width: 15px; height: 15px;
  border: 2px solid var(--brand-soft-2);
  border-top-color: var(--brand);
  border-radius: 50%;
  animation: spin .7s linear infinite;
  flex: 0 0 auto;
}

.progress {
  height: 3px;
  background: var(--surface-3);
  border-radius: 999px;
  overflow: hidden;
  margin-top: 6px;
}
.progress > i {
  display: block;
  height: 100%;
  background: var(--brand);
  border-radius: 999px;
  transition: width .25s ease;
}

/* ---------- Panel de revisión ------------------------------------------ */

.modal {
  position: fixed;
  inset: 0;
  z-index: 60;
  background: rgba(18, 26, 23, .44);
  backdrop-filter: blur(3px);
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 28px 18px;
  overflow-y: auto;
  animation: fade .16s ease both;
}

.modal-card {
  background: var(--surface);
  border-radius: 18px;
  box-shadow: var(--shadow-lg);
  width: min(920px, 100%);
  margin: auto 0;
  animation: rise .2s ease both;
  overflow: hidden;
}
.modal-card.narrow { width: min(560px, 100%); }

.modal-head {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 20px 22px 16px;
  border-bottom: 1px solid var(--line);
}
.modal-head h2 { font-size: 17px; font-weight: 670; letter-spacing: -.015em; }
.modal-head p { font-size: 13px; color: var(--ink-3); margin-top: 2px; }
.modal-head .icon-btn { margin-left: auto; }

.modal-body { padding: 20px 22px; }
.modal-foot {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 15px 22px;
  border-top: 1px solid var(--line);
  background: var(--surface-2);
}

.review-layout {
  display: grid;
  grid-template-columns: 1.15fr .85fr;
  gap: 20px;
  align-items: start;
}

.raw-text {
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  padding: 12px;
  font-family: var(--mono);
  font-size: 11.5px;
  line-height: 1.55;
  color: var(--ink-2);
  max-height: 260px;
  overflow: auto;
  white-space: pre-wrap;
  word-break: break-word;
}
.raw-text mark { background: #fff3bf; color: #6b4a00; padding: 0 1px; border-radius: 2px; }

